162	// Walks every condition node (including untaken branches) and turns it into a
163	// pre-validated, pre-resolved structure. Any malformed condition throws with a
164	// node id and a `$`-style child position, before the workflow can execute.
165	function compileCondition(condition, nodeId, position = '$', depth = 1) {
166	  if (depth > MAX_CONDITION_DEPTH) {
167	    throw new Error(`condition node ${nodeId} at ${position}: conditions must not be nested deeper than ${MAX_CONDITION_DEPTH} levels`);
168	  }
169	  if (!isUsableObject(condition)) {
170	    throw new Error(`condition node ${nodeId} at ${position}: condition must be an object`);
171	  }
172	
173	  const comboKeys = [];
174	  if (Object.hasOwn(condition, 'all')) comboKeys.push('all');
175	  if (Object.hasOwn(condition, 'any')) comboKeys.push('any');
176	  if (Object.hasOwn(condition, 'not')) comboKeys.push('not');
177	  if (comboKeys.length > 1) {
178	    throw new Error(`condition node ${nodeId} at ${position}: condition must use only one of all, any or not`);
179	  }
