197	    }
198	    return {
199	      kind: key,
200	      children: condition[key].map((child, index) =>
201	        compileCondition(child, nodeId, `${position}.${key}[${index}]`, depth + 1)),
202	    };
203	  }
204	
205	  const where = `condition node ${nodeId} at ${position}`;
206	  if (!Object.hasOwn(condition, 'field') || !Object.hasOwn(condition, 'operator')) {
207	    throw new Error(`${where}: condition must be a comparison (field and operator) or a compound (all, any or not)`);
208	  }
209	  const segments = parsePathSegments(condition.field, `${where} field`);
210	
211	  if (!['eq', 'gte', 'lte', 'exists'].includes(condition.operator)) {
212	    throw new Error(`${where}: unknown condition operator: ${condition.operator}`);
213	  }
214	
215	  const unexpected = presentComparisonKeys.filter(key => key !== 'field' && key !== 'operator');
216	  if (condition.operator === 'exists') {
217	    if (unexpected.length > 0) {
218	      throw new Error(`${where}: exists only takes field and operator`);
219	    }
220	    return { kind: 'comparison', operator: 'exists', segments };
221	  }
222	
223	  const hasValue = Object.hasOwn(condition, 'value');
224	  const hasValueField = Object.hasOwn(condition, 'valueField');
225	  if (hasValue === hasValueField) {
226	    throw new Error(`${where}: condition must specify exactly one of value or valueField`);
227	  }
228	  if (hasValueField) {
229	    if (typeof condition.valueField !== 'string') {
230	      throw new Error(`${where} valueField: path must be a non-empty string`);
231	    }
232	    return {
233	      kind: 'comparison', operator: condition.operator, segments,
234	      valueSegments: parsePathSegments(condition.valueField, `${where} valueField`),
235	    };
236	  }
237	  if (!isComparableConstant(condition.value)) {
238	    throw new Error(`${where}: value must be a string, finite number, boolean or null`);
239	  }
240	  const compiled = { kind: 'comparison', operator: condition.operator, segments, value: condition.value };
241	  if (condition.operator !== 'eq') {
242	    compiled.numericValue = toComparableNumber(condition.value);
243	    if (compiled.numericValue === null) {
244	      throw new Error(`${where}: value for ${condition.operator} must convert to a finite number`);
245	    }
246	  }
247	  return compiled;
248	}
249	
250	const formSchemas = new WeakMap();
251	const compiledConditions = new WeakMap();
252	
253	export function validateWorkflow(workflow) {
254	  assertPlainObject(workflow, 'workflow');
255	  if (typeof workflow.id !== 'string' || !workflow.id.trim()) throw new Error('workflow.id is required');
256	  if (typeof workflow.entry !== 'string' || !workflow.entry.trim()) throw new Error('workflow.entry is required');
257	  if (!Array.isArray(workflow.nodes) || workflow.nodes.length === 0) throw new Error('workflow.nodes must not be empty');
258	
259	  const nodes = new Map();
260	  for (const node of workflow.nodes) {
261	    assertPlainObject(node, 'node');
262	    if (typeof node.id !== 'string' || !node.id.trim()) throw new Error('every node requires an id');
263	    if (nodes.has(node.id)) throw new Error(`duplicate node id: ${node.id}`);
264	    if (!NODE_TYPES.has(node.type)) throw new Error(`unsupported node type: ${node.type}`);
265	    nodes.set(node.id, node);
266	  }
267	  if (!nodes.has(workflow.entry)) throw new Error(`entry node does not exist: ${workflow.entry}`);
268	
269	  for (const node of nodes.values()) {
270	    const destinations = node.type === 'condition' ? [node.then, node.else] : node.type === 'end' ? [] : [node.next];
271	    for (const destination of destinations) {
272	      if (typeof destination !== 'string' || !nodes.has(destination)) {
273	        throw new Error(`node ${node.id} points to an unknown destination`);
274	      }
275	    }
276	    if (node.type === 'form') {
277	      formSchemas.set(node, compileFormSchema(node));
278	    }
279	    if (node.type === 'condition') {
280	      compiledConditions.set(node, compileCondition(node.condition, node.id));
281	    }
282	  }
283	  return nodes;
284	}
