286	function lookupOwn(root, segments) {
287	  let current = root;
288	  for (const part of segments) {
289	    if (!isUsableObject(current) || !Object.hasOwn(current, part)) {
290	      return { exists: false };
291	    }
292	    current = current[part];
293	  }
294	  return { exists: true, value: current };
295	}
296	
297	// Evaluates a compiled condition against the cloned execution input. Compounds
298	// short-circuit in declaration order, so a bad value inside a skipped child is
299	// never observed. A non-skipped numeric comparison whose inputs cannot convert
300	// to finite numbers is reported as an invalid_condition error instead.
301	function runCondition(compiled, input, nodeId, position = '$') {
302	  if (compiled.kind === 'not') {
303	    const child = runCondition(compiled.child, input, nodeId, `${position}.not`);
304	    if (!child.ok) return child;
305	    return { ok: true, value: !child.value };
306	  }
307	  if (compiled.kind === 'all' || compiled.kind === 'any') {
308	    for (let i = 0; i < compiled.children.length; i += 1) {
309	      const child = runCondition(compiled.children[i], input, nodeId, `${position}.${compiled.kind}[${i}]`);
310	      if (!child.ok) return child;
311	      if (compiled.kind === 'all' && !child.value) return { ok: true, value: false };
312	      if (compiled.kind === 'any' && child.value) return { ok: true, value: true };
313	    }
314	    return { ok: true, value: compiled.kind === 'all' };
315	  }
316	
317	  const where = `condition node ${nodeId} at ${position}`;
318	  const left = lookupOwn(input, compiled.segments);
319	  if (!left.exists) return { ok: true, value: false };
320	
321	  if (compiled.operator === 'exists') return { ok: true, value: true };
322	
323	  let right;
324	  if (compiled.valueSegments) {
325	    const lookedUp = lookupOwn(input, compiled.valueSegments);
326	    if (!lookedUp.exists) return { ok: true, value: false };
327	    right = lookedUp.value;
328	  } else {
329	    right = compiled.value;
330	  }
331	
332	  if (compiled.operator === 'eq') {
333	    return { ok: true, value: left.value === right };
334	  }
335	
336	  const leftNumber = toComparableNumber(left.value);
337	  if (leftNumber === null) {
338	    return { ok: false, error: `${where}: value at field cannot convert to a finite number` };
339	  }
340	  let rightNumber;
341	  if (compiled.valueSegments) {
342	    rightNumber = toComparableNumber(right);
343	    if (rightNumber === null) {
344	      return { ok: false, error: `${where}: value at valueField cannot convert to a finite number` };
345	    }
346	  } else {
347	    rightNumber = compiled.numericValue;
348	  }
349	  if (compiled.operator === 'gte') return { ok: true, value: leftNumber >= rightNumber };
350	  return { ok: true, value: leftNumber <= rightNumber };
351	}
352	
353	function applyDefault(root, segments, value) {
354	  let current = root;
355	  for (let i = 0; i < segments.length - 1; i += 1) {
356	    const part = segments[i];
357	    if (Object.hasOwn(current, part)) {
358	      const next = current[part];
359	      if (!isUsableObject(next)) return false;
360	      current = next;
361	    } else {
362	      const created = {};
363	      current[part] = created;
364	      current = created;
365	    }
366	  }
367	  current[segments[segments.length - 1]] = value;
368	  return true;
369	}
370	
371	function processFormField(spec, input, nodeId) {
372	  const error = code => ({ nodeId, path: spec.path, code });
373	  const { exists, value } = lookupOwn(input, spec.segments);
374	
375	  if (!exists) {
376	    if (spec.hasDefault) {
377	      if (!isUsableObject(input) || !applyDefault(input, spec.segments, spec.default)) {
378	        return error('type');
379	      }
380	      return null;
381	    }
382	    return spec.required ? error('required') : null;
383	  }
384	
385	  if (!valueMatchesType(value, spec.type)) return error('type');
386	  if (!valueSatisfiesBounds(value, spec)) {
387	    return error(spec.type === 'string' ? 'length' : 'range');
388	  }
389	  return null;
390	}
391	
392	function processForm(node, input, compiled) {
393	  const snapshot = structuredClone(input);
394	  const errors = [];
395	  for (const spec of compiled) {
396	    const fieldError = processFormField(spec, input, node.id);
397	    if (fieldError) errors.push(fieldError);
398	  }
399	  return errors.length === 0
400	    ? { ok: true }
401	    : { ok: false, errors, rollback: snapshot };
402	}
403	
404	export function executeWorkflow(workflow, input = {}) {
405	  const nodes = validateWorkflow(workflow);
406	  const trace = [];
407	  const context = { input: structuredClone(input), output: {} };
408	  let currentId = workflow.entry;
409	
410	  for (let step = 0; step <= nodes.size; step += 1) {
411	    const node = nodes.get(currentId);
412	    trace.push({ nodeId: node.id, type: node.type });
413	    if (node.type === 'end') return { status: 'completed', result: node.result ?? null, context, trace };
414	    if (node.type === 'action') context.output[node.id] = node.message ?? `action:${node.id}`;
415	    if (node.type === 'form') {
416	      const compiled = formSchemas.get(node);
417	      if (compiled) {
418	        const formResult = processForm(node, context.input, compiled);
419	        if (!formResult.ok) {
420	          context.input = formResult.rollback;
421	          return { status: 'invalid_input', context, trace, errors: formResult.errors };
422	        }
423	      }
424	    }
425	    if (node.type === 'condition') {
426	      const outcome = runCondition(compiledConditions.get(node), context.input, node.id);
427	      if (!outcome.ok) {
428	        return { status: 'invalid_condition', context, trace, error: outcome.error };
429	      }
430	      currentId = outcome.value ? node.then : node.else;
431	    } else {
432	      currentId = node.next;
433	    }
434	  }
435	  throw new Error('workflow did not terminate; a cycle is present');
436	}
