278	// Resolves a node's explicit dependencies. Dependencies only decide when a
279	// node may run; they never activate it. An empty array is the default.
280	function parseDependencies(node, nodes, isEntry) {
281	  if (!Object.hasOwn(node, 'dependsOn') || node.dependsOn === undefined) return [];
282	  if (!Array.isArray(node.dependsOn)) throw new Error(`node ${node.id}: dependsOn must be an array`);
283	  if (node.dependsOn.length === 0) return [];
284	  if (isEntry) throw new Error(`entry node ${node.id} must not declare dependencies`);
285	  const ids = [];
286	  const seen = new Set();
287	  for (const id of node.dependsOn) {
288	    if (typeof id !== 'string') throw new Error(`node ${node.id}: dependsOn must contain only node ids`);
289	    if (!nodes.has(id)) throw new Error(`node ${node.id} depends on an unknown node: ${id}`);
290	    if (id === node.id) throw new Error(`node ${node.id}: dependsOn must not reference itself`);
291	    if (seen.has(id)) throw new Error(`node ${node.id}: dependsOn must not contain duplicate ids`);
292	    seen.add(id);
293	    ids.push(id);
294	  }
295	  return ids;
296	}
