298	// Detects cycles over the union of flow edges (outlets) and dependency
299	// precedence edges. "b dependsOn a" means a must precede b, so the precedence
300	// edge is a -> b (dependency -> dependent). Includes nodes no branch ever
301	// reaches. The reported chain starts and ends with the same id, and every
302	// step is a real outlet or dependency precedence relation.
303	function detectCycle(workflow, successors, dependencies) {
304	  const precedence = new Map();
305	  for (const node of workflow.nodes) precedence.set(node.id, []);
306	  for (const node of workflow.nodes) {
307	    for (const succ of successors.get(node.id)) {
308	      precedence.get(node.id).push(succ);
309	    }
310	    for (const dep of dependencies.get(node.id)) {
311	      precedence.get(dep).push(node.id);
312	    }
313	  }
314	
315	  const color = new Map();
316	  for (const node of workflow.nodes) color.set(node.id, 0);
317	  for (const startNode of workflow.nodes) {
318	    if (color.get(startNode.id) !== 0) continue;
319	    const path = [startNode.id];
320	    const stack = [{ id: startNode.id, edgeIndex: 0 }];
321	    color.set(startNode.id, 1);
322	    while (stack.length > 0) {
323	      const frame = stack[stack.length - 1];
324	      const edges = precedence.get(frame.id);
325	      if (frame.edgeIndex < edges.length) {
326	        const next = edges[frame.edgeIndex];
327	        frame.edgeIndex += 1;
328	        const state = color.get(next);
329	        if (state === 1) {
330	          const start = path.indexOf(next);
331	          const cycle = [...path.slice(start), next];
332	          throw new Error(`workflow cycle is present: ${cycle.join(' -> ')}`);
333	        }
334	        if (state === 0) {
335	          color.set(next, 1);
336	          path.push(next);
337	          stack.push({ id: next, edgeIndex: 0 });
338	        }
339	      } else {
340	        color.set(frame.id, 2);
341	        path.pop();
342	        stack.pop();
343	      }
344	    }
345	  }
346	}
