348	export function validateWorkflow(workflow) {
349	  assertPlainObject(workflow, 'workflow');
350	  if (typeof workflow.id !== 'string' || !workflow.id.trim()) throw new Error('workflow.id is required');
351	  if (typeof workflow.entry !== 'string' || !workflow.entry.trim()) throw new Error('workflow.entry is required');
