422	function runCondition(compiled, input, nodeId, position = '$') {
423	  if (compiled.kind === 'not') {
424	    const child = runCondition(compiled.child, input, nodeId, `${position}.not`);
425	    if (!child.ok) return child;
426	    return { ok: true, value: !child.value };
427	  }
428	  if (compiled.kind === 'all' || compiled.kind === 'any') {
429	    for (let i = 0; i < compiled.children.length; i += 1) {
430	      const child = runCondition(compiled.children[i], input, nodeId, `${position}.${compiled.kind}[${i}]`);
431	      if (!child.ok) return child;
432	      if (compiled.kind === 'all' && !child.value) return { ok: true, value: false };
433	      if (compiled.kind === 'any' && child.value) return { ok: true, value: true };
434	    }
435	    return { ok: true, value: compiled.kind === 'all' };
436	  }
