438	  const where = `condition node ${nodeId} at ${position}`;
439	  const left = lookupOwn(input, compiled.segments);
440	  if (!left.exists) return { ok: true, value: false };
441	
442	  if (compiled.operator === 'exists') return { ok: true, value: true };
443	
444	  let right;
445	  if (compiled.valueSegments) {
446	    const lookedUp = lookupOwn(input, compiled.valueSegments);
447	    if (!lookedUp.exists) return { ok: true, value: false };
448	    right = lookedUp.value;
449	  } else {
450	    right = compiled.value;
451	  }
452	
453	  if (compiled.operator === 'eq') {
454	    return { ok: true, value: left.value === right };
455	  }
456	
457	  const leftNumber = toComparableNumber(left.value);
458	  if (leftNumber === null) {
459	    return { ok: false, error: `${where}: value at field cannot convert to a finite number` };
460	  }
461	  let rightNumber;
462	  if (compiled.valueSegments) {
463	    rightNumber = toComparableNumber(right);
464	    if (rightNumber === null) {
465	      return { ok: false, error: `${where}: value at valueField cannot convert to a finite number` };
466	    }
467	  } else {
468	    rightNumber = compiled.numericValue;
469	  }
470	  if (compiled.operator === 'gte') return { ok: true, value: leftNumber >= rightNumber };
471	  return { ok: true, value: leftNumber <= rightNumber };
472	}
