474	function applyDefault(root, segments, value) {
475	  let current = root;
476	  for (let i = 0; i < segments.length - 1; i += 1) {
477	    const part = segments[i];
478	    if (Object.hasOwn(current, part)) {
479	      const next = current[part];
480	      if (!isUsableObject(next)) return false;
481	      current = next;
482	    } else {
483	      const created = {};
484	      current[part] = created;
485	      current = created;
486	    }
487	  }
488	  current[segments[segments.length - 1]] = value;
489	  return true;
490	}
