492	function processFormField(spec, input, nodeId) {
493	  const error = code => ({ nodeId, path: spec.path, code });
494	  const { exists, value } = lookupOwn(input, spec.segments);
495	
496	  if (!exists) {
497	    if (spec.hasDefault) {
498	      if (!isUsableObject(input) || !applyDefault(input, spec.segments, spec.default)) {
499	        return error('type');
500	      }
501	      return null;
502	    }
503	    return spec.required ? error('required') : null;
504	  }
505	
506	  if (!valueMatchesType(value, spec.type)) return error('type');
507	  if (!valueSatisfiesBounds(value, spec)) {
508	    return error(spec.type === 'string' ? 'length' : 'range');
509	  }
510	  return null;
511	}
