513	function processForm(node, input, compiled) {
514	  const snapshot = structuredClone(input);
515	  const errors = [];
516	  for (const spec of compiled) {
517	    const fieldError = processFormField(spec, input, node.id);
518	    if (fieldError) errors.push(fieldError);
519	  }
520	  return errors.length === 0
521	    ? { ok: true }
522	    : { ok: false, errors, rollback: snapshot };
523	}
524	
525	function normalizeOutlet(value) {
526	  return Array.isArray(value) ? value : [value];
527	}
