529	// Runs the workflow as a deterministic scheduler. The entry node starts
530	// activated; other nodes activate only when a traversed outlet reaches them
531	// (dependencies never activate). Each turn picks the first activated node
532	// whose explicit dependencies have all completed, in nodes declaration order.
533	// A node runs at most once. When nothing can run, either all activated nodes
534	// completed (completed) or some wait on dependencies that may never arrive
535	// (blocked).
536	export function executeWorkflow(workflow, input = {}) {
537	  const nodes = validateWorkflow(workflow);
538	  const nodeIndex = new Map();
539	  workflow.nodes.forEach((node, index) => nodeIndex.set(node.id, index));
540	  const trace = [];
541	  const context = { input: structuredClone(input), output: {} };
542	
543	  const activated = new Set([workflow.entry]);
544	  const completed = new Set();
545	
546	  const dependenciesOf = node => node.dependsOn ?? [];
547	
548	  while (true) {
549	    let current = null;
550	    for (const node of workflow.nodes) {
551	      if (!activated.has(node.id) || completed.has(node.id)) continue;
552	      if (dependenciesOf(node).every(id => completed.has(id))) {
553	        current = node;
554	        break;
555	      }
556	    }
557	
558	    if (current === null) {
559	      const waiting = workflow.nodes.filter(node => activated.has(node.id) && !completed.has(node.id));
560	      if (waiting.length === 0) {
561	        const endNode = workflow.nodes.find(node => node.type === 'end' && completed.has(node.id));
562	        return { status: 'completed', result: endNode ? (endNode.result ?? null) : null, context, trace };
563	      }
564	      const blockedNodes = waiting.map(node => ({
565	        nodeId: node.id,
566	        missingDependencies: dependenciesOf(node)
567	          .filter(id => !completed.has(id))
568	          .sort((a, b) => nodeIndex.get(a) - nodeIndex.get(b)),
569	      }));
570	      return { status: 'blocked', context, trace, blockedNodes };
571	    }
572	
573	    trace.push({ nodeId: current.id, type: current.type });
574	
575	    if (current.type === 'end') {
576	      completed.add(current.id);
577	      continue;
578	    }
579	    if (current.type === 'action') {
580	      context.output[current.id] = current.message ?? `action:${current.id}`;
581	      for (const id of normalizeOutlet(current.next)) activated.add(id);
582	      completed.add(current.id);
583	      continue;
584	    }
585	    if (current.type === 'form') {
586	      const compiled = formSchemas.get(current);
587	      if (compiled) {
588	        const formResult = processForm(current, context.input, compiled);
589	        if (!formResult.ok) {
590	          context.input = formResult.rollback;
591	          return { status: 'invalid_input', context, trace, errors: formResult.errors };
592	        }
593	      }
594	      for (const id of normalizeOutlet(current.next)) activated.add(id);
595	      completed.add(current.id);
596	      continue;
597	    }
598	    if (current.type === 'condition') {
599	      const outcome = runCondition(compiledConditions.get(current), context.input, current.id);
600	      if (!outcome.ok) {
601	        return { status: 'invalid_condition', context, trace, error: outcome.error };
602	      }
603	      for (const id of normalizeOutlet(outcome.value ? current.then : current.else)) {
604	        activated.add(id);
605	      }
606	      completed.add(current.id);
607	      continue;
608	    }
609	    // trigger
610	    for (const id of normalizeOutlet(current.next)) {
611	      activated.add(id);
612	    }
613	    completed.add(current.id);
614	  }
615	}
